package com.sobrenaturaldirector.decision.utility;
public final class FactorResult { private final String factorId; private final double rawValue, normalizedValue, weight, contribution; public FactorResult(String id,double raw,double normalized,double weight){if(!finite(raw)||!finite(normalized)||!finite(weight))throw new IllegalArgumentException("non-finite factor");factorId=id;rawValue=raw;normalizedValue=normalized;this.weight=weight;contribution=normalized*weight;} private static boolean finite(double x){return !Double.isNaN(x)&&!Double.isInfinite(x);} public String getFactorId(){return factorId;} public double getRawValue(){return rawValue;} public double getNormalizedValue(){return normalizedValue;} public double getWeight(){return weight;} public double getContribution(){return contribution;} }
